def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_D = 0
    opp_D = 0
    unprov = 0
    cc = 0
    cd = 0
    dc = 0
    dd = 0
    prev_my = 'C'

    for m, o in history:
        if m == 'D':
            my_D += 1
        if o == 'D':
            opp_D += 1
            if prev_my == 'C':
                unprov += 1
        if m == 'C':
            if o == 'C':
                cc += 1
            else:
                cd += 1
        else:
            if o == 'C':
                dc += 1
            else:
                dd += 1
        prev_my = m

    if opp_D == 0:
        if n == 1:
            return 'D'
        if n == 2:
            return 'C'
        return 'D'

    window = history[-8:]
    recent_opp_D = 0
    recent_my_D = 0
    for m, o in window:
        if o == 'D':
            recent_opp_D += 1
        if m == 'D':
            recent_my_D += 1

    c_streak = 0
    for pair in reversed(history):
        if pair[1] == 'C':
            c_streak += 1
        else:
            break

    d_streak = 0
    for pair in reversed(history):
        if pair[1] == 'D':
            d_streak += 1
        else:
            break

    last_my, last_op = history[-1]
    provoked = n >= 2 and history[-2][0] == 'D'
    my_score = 3 * cc + 5 * dc + dd
    opp_score = 3 * cc + 5 * cd + dd

    if n == 99:
        if last_op == 'D':
            return 'D'
        if unprov == 0 and opp_D <= 1 and recent_opp_D <= 1:
            return 'D'
        return 'C'

    if last_op == 'D':
        if last_my == 'D' and recent_opp_D <= 1 and unprov <= 2 and opp_D <= 8:
            return 'C'
        if provoked:
            if unprov >= 2 or recent_opp_D >= 4 or opp_D * 2 >= n:
                return 'D'
            return 'C'
        if d_streak == 2 and n >= 3 and history[-3][0] == 'D' and recent_my_D <= 1 and recent_opp_D == 2:
            return 'C'
        return 'D'

    if unprov == 0 and opp_D <= 2 and recent_opp_D <= 1 and c_streak >= 12:
        return 'C'

    if recent_opp_D >= 3 and opp_D * 3 >= n:
        if rng.random() < 0.4:
            return 'D'

    if opp_score > my_score + 12 and unprov >= 1 and opp_D * 4 <= n:
        if rng.random() < 0.25:
            return 'D'

    return 'C'
